# Build final grid with pattern [5, 5, 8, 5, 8, 8, 5, 0] assigned to 8 markers
pattern = [5, 5, 8, 5, 8, 8, 5, 0]

markers = [
    (1, 2), (1, 9), (6, 12), (7, 4), (12, 2), (13, 11), (17, 4), (17, 8)
]

prefix = []
for row in range(20):
    if row in [0, 2, 3, 4, 5, 8, 9, 10, 11, 14, 15, 16, 18, 19]:
        prefix.append(f"Row {row}: all 4s")
    else:
        vals = [4]*13
        if row == 1:
            vals[2] = pattern[0]  # 5
            vals[9] = pattern[1]  # 5
        elif row == 6:
            vals[12] = pattern[2]  # 8
        elif row == 7:
            vals[4] = pattern[3]  # 5
        elif row == 12:
            vals[2] = pattern[4]  # 8
        elif row == 13:
            vals[11] = pattern[5]  # 8
        elif row == 17:
            vals[4] = pattern[6]  # 5
            vals[8] = pattern[7]  # 0
        prefix.append(f"Row {row}: marker vals = {prefix}")

print("Marker assignments:")
for i, (r, c) in enumerate(markers):
    print(f"  Marker ({r}, {c}): value = {pattern[i]}")

